import { supabase } from './client'
import type { ProjectTemplate } from '@/entities/project/types'

export const templatesService = {
  async listTemplates(tenantId?: string): Promise<ProjectTemplate[]> {
    let query = supabase.from('templates').select('*').order('created_at', { ascending: false })
    if (tenantId) query = query.or(`tenant_id.eq.${tenantId},type.eq.public`)
    const { data, error } = await query
    if (error) throw error
    return (data ?? []) as ProjectTemplate[]
  },
}
